"use client";

import { Dialog } from "@base-ui/react/dialog";
import * as React from "react";
import { overlayClassNames, overlayZIndex } from "../tokens/components/overlay";
import { cn } from "../utils/cn";
import type {
  CommandEmptyProps,
  CommandGroupProps,
  CommandInputProps,
  CommandItemProps,
  CommandListProps,
  CommandResultsProps,
  CommandSeparatorProps,
  CommandShortcutProps,
} from "./command";
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
  CommandResults,
  CommandSeparator,
  CommandShortcut,
} from "./command";
import { commandFrameClassName } from "./command-styles";
import { DialogOverlay, DialogPortal } from "./dialog";

// =============================================================================
// Types
// =============================================================================

export interface CommandMenuRootProps {
  /** Whether the command menu is open */
  open: boolean;
  /** Setter to control the open state */
  setOpen: (open: boolean) => void;
  /** Accessible label announced by screen readers (defaults to "Command Menu") */
  label?: string;
  /** Optional hidden description for assistive technology */
  description?: string;
  /** Additional classes for the overlay panel */
  className?: string;
  /** Additional classes for the cmdk frame */
  commandClassName?: string;
  children?: React.ReactNode;
}

export type CommandMenuItemProps = CommandItemProps & {
  /** Callback invoked when the item is selected. Prefer `onSelect` for new code. */
  callback?: () => void;
  className?: string;
  onSelect?: (value: string) => void;
};

const commandMenuSurfaceClassName = overlayClassNames.commandSurface;

// =============================================================================
// CommandMenuRoot
// =============================================================================

export function CommandMenuRoot({
  open,
  setOpen,
  label = "Command Menu",
  description,
  className,
  commandClassName,
  children,
}: CommandMenuRootProps) {
  return (
    <Dialog.Root open={open} onOpenChange={setOpen}>
      <DialogPortal>
        <DialogOverlay />
        <Dialog.Popup
          className={cn(commandMenuSurfaceClassName, className)}
          style={{ zIndex: overlayZIndex.modal }}
        >
          {/* Visually-hidden title for screen reader accessibility (WCAG 4.1.2) */}
          <Dialog.Title className="sr-only">{label}</Dialog.Title>
          {description ? (
            <Dialog.Description className="sr-only">{description}</Dialog.Description>
          ) : null}
          <Command className={cn(commandFrameClassName, commandClassName)}>{children}</Command>
        </Dialog.Popup>
      </DialogPortal>
    </Dialog.Root>
  );
}
CommandMenuRoot.displayName = "CommandMenu.Root";

// =============================================================================
// CommandMenuItem
// =============================================================================

export const CommandMenuItem = ({
  callback,
  className,
  onSelect,
  ref,
  ...props
}: CommandMenuItemProps & {
  ref?: React.Ref<React.ElementRef<typeof CommandItem>> | undefined;
}) => {
  const handleSelect = React.useCallback(
    (value: string) => {
      onSelect?.(value);
      callback?.();
    },
    [callback, onSelect],
  );

  return <CommandItem ref={ref} onSelect={handleSelect} className={className} {...props} />;
};
CommandMenuItem.displayName = "CommandMenu.Item";

// =============================================================================
// Pass-through sub-components (typed aliases)
// =============================================================================

export const CommandMenuInput = ({
  ref,
  ...props
}: CommandInputProps & { ref?: React.Ref<React.ElementRef<typeof CommandInput>> | undefined }) => (
  <CommandInput ref={ref} {...props} />
);
CommandMenuInput.displayName = "CommandMenu.Input";

export const CommandMenuList = ({
  ref,
  ...props
}: CommandListProps & { ref?: React.Ref<React.ElementRef<typeof CommandList>> | undefined }) => (
  <CommandList ref={ref} {...props} />
);
CommandMenuList.displayName = "CommandMenu.List";

export const CommandMenuEmpty = ({
  ref,
  ...props
}: CommandEmptyProps & { ref?: React.Ref<React.ElementRef<typeof CommandEmpty>> | undefined }) => (
  <CommandEmpty ref={ref} {...props} />
);
CommandMenuEmpty.displayName = "CommandMenu.Empty";

export const CommandMenuResults = ({
  ref,
  ...props
}: CommandResultsProps & {
  ref?: React.Ref<React.ElementRef<typeof CommandResults>> | undefined;
}) => <CommandResults ref={ref} {...props} />;
CommandMenuResults.displayName = "CommandMenu.Results";

export const CommandMenuGroup = ({
  ref,
  ...props
}: CommandGroupProps & { ref?: React.Ref<React.ElementRef<typeof CommandGroup>> | undefined }) => (
  <CommandGroup ref={ref} {...props} />
);
CommandMenuGroup.displayName = "CommandMenu.Group";

export const CommandMenuSeparator = ({
  ref,
  ...props
}: CommandSeparatorProps & {
  ref?: React.Ref<React.ElementRef<typeof CommandSeparator>> | undefined;
}) => <CommandSeparator ref={ref} {...props} />;
CommandMenuSeparator.displayName = "CommandMenu.Separator";

export const CommandMenuShortcut = ({ ...props }: CommandShortcutProps) => (
  <CommandShortcut {...props} />
);
CommandMenuShortcut.displayName = "CommandMenu.Shortcut";

import { cn } from "../utils/cn";

export const commandFrameClassName = cn(
  "[&_[cmdk-group-heading]]:px-2 [&_[cmdk-group-heading]]:font-medium",
  "[&_[cmdk-group-heading]]:text-muted-foreground",
  "[&_[cmdk-group]:not([hidden])_~[cmdk-group]]:pt-0",
  "[&_[cmdk-group]]:px-2",
  "[&_[data-cmdk-input-wrapper]_svg]:h-5 [&_[data-cmdk-input-wrapper]_svg]:w-5",
  "[&_[cmdk-input]]:h-12",
  "[&_[cmdk-item]]:px-2 [&_[cmdk-item]]:py-2.5",
  "[&_[cmdk-item]_svg]:h-4 [&_[cmdk-item]_svg]:w-4",
);

export const commandInputWrapperClassName = cn(
  "flex items-center border-b border-border px-3",
  "transition-[border-color] duration-micro ease-out",
  "has-[:focus-visible]:border-ring/60",
);

export const commandInputClassName = cn(
  "flex h-11 w-full appearance-none border-0 bg-transparent py-3 text-sm text-foreground shadow-none outline-none",
  "placeholder:text-muted-foreground disabled:cursor-not-allowed disabled:opacity-50",
  "outline-none focus-visible:outline-none",
  "[&::-webkit-search-cancel-button]:appearance-none",
  "[&::-webkit-search-decoration]:appearance-none",
  "[&::-webkit-search-results-button]:appearance-none",
  "[&::-webkit-search-results-decoration]:appearance-none",
);

/**
 * Primitive Design Tokens — Layer 1
 *
 * Raw values only. No CSS variable references, no semantic meaning.
 * These are the "atoms" of the design system.
 *
 * Color source: @nebutra/brand `colors` → @nebutra/design-tokens `tokens/core.json` (SSOT).
 * Typography:   Geist + Geist Mono (Vercel) with Noto Sans SC + PingFang SC + Microsoft YaHei CJK fallbacks.
 *               Aligned with @nebutra/design-tokens SSOT.
 */

import { colors } from "@nebutra/brand";

// ─── Color Palette ────────────────────────────────────────────────────────────

export const primitiveColors = {
  // Nebutra Blue (云毓蓝) — technology & trust — VI: #0033FE
  blue50: colors.primary[50],
  blue100: colors.primary[100],
  blue200: colors.primary[200],
  blue300: colors.primary[300],
  blue400: colors.primary[400],
  blue500: colors.primary[500], // brand primary
  blue600: colors.primary[600],
  blue700: colors.primary[700],
  blue800: colors.primary[800],
  blue900: colors.primary[900],
  blue950: colors.primary[950],

  // Nebutra Cyan (云毓青) — data flow & intelligence — VI: #0BF1C3
  cyan50: colors.accent[50],
  cyan100: colors.accent[100],
  cyan200: colors.accent[200],
  cyan300: colors.accent[300],
  cyan400: colors.accent[400],
  cyan500: colors.accent[500], // brand secondary
  cyan600: colors.accent[600],
  cyan700: colors.accent[700],
  cyan800: colors.accent[800],
  cyan900: colors.accent[900],
  cyan950: colors.accent[950],

  // Neutral (blue-undertone gray scale)
  neutral50: colors.neutral[50],
  neutral100: colors.neutral[100],
  neutral200: colors.neutral[200],
  neutral300: colors.neutral[300],
  neutral400: colors.neutral[400],
  neutral500: colors.neutral[500],
  neutral600: colors.neutral[600],
  neutral700: colors.neutral[700],
  neutral800: colors.neutral[800],
  neutral900: colors.neutral[900],
  neutral950: colors.neutral[950], // deepest — used as dark background

  // Semantic raw colors — VI §Color Specifications
  // NOTE: info = brand blue (#0033FE), not sky/teal
  red500: "#ef4444",
  red600: "#dc2626",
  green500: "#22c55e", // VI manual specifies this exact value for success
  green600: "#16a34a",
  amber500: "#f59e0b",
  amber600: "#d97706",

  white: colors.white,
  black: colors.black,
} as const;

export type PrimitiveColor = keyof typeof primitiveColors;

// ─── Brand Gradients — VI §Brand Gradients (first-class design assets) ────────

export const primitiveGradients = {
  /** Hero sections, primary CTA buttons, logo fills — VI signature gradient */
  primary: colors.gradient.primary,
  /** Hover states, secondary gradient elements */
  reverse: colors.gradient.primaryReverse,
  /** Vertical layout dividers, page section separators */
  vertical: colors.gradient.primaryVertical,
  /** Background halos, focus glow effects, radial emphasis */
  radial: colors.gradient.primaryRadial,
  /** Dark mode card surfaces — deep brand-blue tinted */
  darkCard: "linear-gradient(135deg, #020617 0%, #0a1628 100%)",
} as const;

export type PrimitiveGradient = keyof typeof primitiveGradients;

// ─── Spacing Scale (px values) ────────────────────────────────────────────────

export const primitiveSpacing = {
  0: 0,
  1: 4,
  2: 8,
  3: 12,
  4: 16,
  5: 20,
  6: 24,
  8: 32,
  10: 40,
  12: 48,
  14: 56,
  16: 64,
  20: 80,
  24: 96,
} as const;

export type PrimitiveSpacing = keyof typeof primitiveSpacing;

// ─── Layout Containers (px) — max-width standards ────────────────────────────
// Use `text` for text-heavy sections (hero copy, CTA), `content` for general
// sections, and `wide` for full-bleed feature bento grids.

export const primitiveContainer = {
  /** Text-focused: hero headlines, CTA copy, FAQ — optimized for reading */
  text: 896, // ~56rem / max-w-4xl
  /** Standard content sections: pricing, architecture, blog */
  content: 1152, // ~72rem / max-w-6xl
  /** Wide sections: feature bento, testimonials, product demos */
  wide: 1400, // ~87.5rem — Vercel/Supabase standard
} as const;

export type PrimitiveContainer = keyof typeof primitiveContainer;

// ─── Sizing Scale — component heights (px) ────────────────────────────────────

export const primitiveSizing = {
  xs: 20,
  /** Geist button-specific size (24px). Larger than xs by design. */
  tiny: 24,
  sm: 32,
  md: 40,
  lg: 48,
  xl: 56,
  "2xl": 80,
} as const;

export type PrimitiveSizing = keyof typeof primitiveSizing;

// ─── Border Radius (px) ───────────────────────────────────────────────────────

export const primitiveRadius = {
  none: 0,
  sm: 4,
  md: 6, // Geist default — slightly more rounded than 4px
  lg: 8,
  xl: 12,
  "2xl": 16,
  full: 9999,
} as const;

export type PrimitiveRadius = keyof typeof primitiveRadius;

// ─── Font Sizes (px) ──────────────────────────────────────────────────────────

export const primitiveFontSize = {
  xs: 12,
  sm: 14,
  base: 16,
  lg: 18,
  xl: 20,
  "2xl": 24,
  "3xl": 30,
  "4xl": 36,
} as const;

export type PrimitiveFontSize = keyof typeof primitiveFontSize;

// ─── Font Weights ─────────────────────────────────────────────────────────────

export const primitiveFontWeight = {
  light: 300,
  normal: 400,
  medium: 500,
  semibold: 600,
  bold: 700,
} as const;

export type PrimitiveFontWeight = keyof typeof primitiveFontWeight;

// ─── Font Families — VI §Typography ──────────────────────────────────────────
// Aligned with @nebutra/design-tokens SSOT (tokens/core.json fontFamily.*).
// EN primary: Geist (Vercel variable, 100–900)
// EN mono:    Geist Mono
// CN primary: Noto Sans SC → PingFang SC → Microsoft YaHei → vivo Sans (print)

export const primitiveFontFamily = {
  /** Default body/UI stack — Geist with CJK auto-fallbacks */
  sans: '"Geist", "Noto Sans SC", "PingFang SC", "Microsoft YaHei", -apple-system, BlinkMacSystemFont, system-ui, sans-serif',
  /** Chinese body/UI stack */
  cnSans: '"Noto Sans SC", "PingFang SC", "Microsoft YaHei", "vivo Sans", sans-serif',
  /** Display / hero headlines */
  display: '"Geist", "Noto Sans SC", sans-serif',
  /** Heading (alias of display) */
  heading: '"Geist", "Noto Sans SC", sans-serif',
  /** Code / monospace — Geist Mono pairs with Geist for full family coverage */
  mono: '"Geist Mono", ui-monospace, SFMono-Regular, "SF Mono", Menlo, monospace',
} as const;

export type PrimitiveFontFamily = keyof typeof primitiveFontFamily;

// ─── Shadows ──────────────────────────────────────────────────────────────────

export const primitiveShadow = {
  none: "none",
  sm: "0 1px 2px 0 rgb(0 0 0 / 0.05)",
  md: "0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1)",
  lg: "0 10px 15px -3px rgb(0 0 0 / 0.1), 0 4px 6px -4px rgb(0 0 0 / 0.1)",
  xl: "0 20px 25px -5px rgb(0 0 0 / 0.1), 0 8px 10px -6px rgb(0 0 0 / 0.1)",
  /** Brand glow — blue tone for focus/highlight states */
  brandGlow: "0 0 0 3px rgb(0 51 254 / 0.15)",
} as const;

export type PrimitiveShadow = keyof typeof primitiveShadow;

// ─── Transition ───────────────────────────────────────────────────────────────

/**
 * Primitive transition tokens — aligned with the four-rail motion scale
 * (SSOT: @nebutra/design-tokens core.json → duration.*).
 * Keys mirror semantic.json motion.duration.*; values are in ms.
 */
export const primitiveTransition = {
  duration: {
    micro: 100, // hover, focus, small state changes
    flow: 200, // standard state transitions (default)
    reveal: 300, // larger motion (accordion, modal, drawer)
    cinematic: 500, // hero entrance, big delight moments
  },
  easing: {
    default: "ease-out",
    spring: "cubic-bezier(0.34, 1.56, 0.64, 1)",
    inOut: "cubic-bezier(0.4, 0, 0.2, 1)",
  },
} as const;

// ─── Focus Ring ───────────────────────────────────────────────────────────────

export const primitiveFocusRing = {
  width: 2, // px
  offset: 2, // px — gap between element and ring
} as const;

"use client";

import { MagnifyingGlass as Search } from "@nebutra/icons";
import { Command as CommandPrimitive } from "cmdk";
import * as React from "react";
import { cn } from "../utils/cn";
import {
  commandFrameClassName,
  commandInputClassName,
  commandInputWrapperClassName,
} from "./command-styles";
import { Dialog, DialogContent } from "./dialog";
import { Kbd } from "./kbd";
import { overlayPrimitiveClassNames } from "./overlay";

export type CommandProps = React.ComponentPropsWithoutRef<typeof CommandPrimitive>;

export type CommandDialogProps = React.ComponentPropsWithoutRef<typeof Dialog> & {
  children?: React.ReactNode;
};

export type CommandInputProps = React.ComponentPropsWithoutRef<typeof CommandPrimitive.Input>;

export type CommandListProps = React.ComponentPropsWithoutRef<typeof CommandPrimitive.List>;

export type CommandEmptyProps = React.ComponentPropsWithoutRef<typeof CommandPrimitive.Empty>;

export type CommandGroupProps = React.ComponentPropsWithoutRef<typeof CommandPrimitive.Group>;

export type CommandSeparatorProps = React.ComponentPropsWithoutRef<
  typeof CommandPrimitive.Separator
>;

export type CommandItemProps = React.ComponentPropsWithoutRef<typeof CommandPrimitive.Item>;

export interface CommandShortcutProps extends React.HTMLAttributes<HTMLSpanElement> {
  /** Render each shortcut token as a separate Kbd key. */
  keys?: ReadonlyArray<React.ReactNode>;
  /** Accessible label for compact shortcut glyphs. */
  label?: string;
}

export interface CommandResultsProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Current visible result count. Pass from product state when known. */
  count?: number;
  /** Current search query, used only for the default screen-reader message. */
  search?: string;
  /** Custom screen-reader announcement. */
  label?: (count: number | undefined, search: string) => React.ReactNode;
}

/**
 * Command - A command palette / autocomplete component
 *
 * @description
 * Based on cmdk, provides a fast, composable command palette interface.
 * Can be used standalone or inside a dialog.
 *
 * @example Basic usage
 * ```tsx
 * <Command>
 *   <CommandInput placeholder="Search..." />
 *   <CommandList>
 *     <CommandEmpty>No results found.</CommandEmpty>
 *     <CommandGroup heading="Suggestions">
 *       <CommandItem>Calendar</CommandItem>
 *       <CommandItem>Search</CommandItem>
 *     </CommandGroup>
 *   </CommandList>
 * </Command>
 * ```
 *
 * @example In dialog
 * ```tsx
 * <CommandDialog open={open} onOpenChange={setOpen}>
 *   <CommandInput placeholder="Type a command..." />
 *   <CommandList>
 *     <CommandGroup heading="Actions">
 *       <CommandItem>New File</CommandItem>
 *       <CommandItem>Settings</CommandItem>
 *     </CommandGroup>
 *   </CommandList>
 * </CommandDialog>
 * ```
 */
const Command = ({
  className,
  ref,
  ...props
}: CommandProps & { ref?: React.Ref<React.ElementRef<typeof CommandPrimitive>> | undefined }) => (
  <CommandPrimitive
    ref={ref}
    className={cn(
      "flex h-full w-full flex-col overflow-hidden",
      overlayPrimitiveClassNames.commandFrame,
      className,
    )}
    {...props}
  />
);
Command.displayName = CommandPrimitive.displayName;

const CommandDialog = ({ children, ...props }: CommandDialogProps) => {
  return (
    <Dialog {...props}>
      <DialogContent
        className={cn(
          overlayPrimitiveClassNames.modalSurface,
          overlayPrimitiveClassNames.commandDialogSurface,
        )}
      >
        <Command className={commandFrameClassName}>{children}</Command>
      </DialogContent>
    </Dialog>
  );
};

const CommandInput = ({
  className,
  ref,
  ...props
}: CommandInputProps & {
  ref?: React.Ref<React.ElementRef<typeof CommandPrimitive.Input>> | undefined;
}) => (
  <div className={commandInputWrapperClassName} data-cmdk-input-wrapper="">
    <Search className="mr-2 h-4 w-4 shrink-0 opacity-50" />
    <CommandPrimitive.Input ref={ref} className={cn(commandInputClassName, className)} {...props} />
  </div>
);
CommandInput.displayName = CommandPrimitive.Input.displayName;

const CommandList = ({
  className,
  ref,
  ...props
}: CommandListProps & {
  ref?: React.Ref<React.ElementRef<typeof CommandPrimitive.List>> | undefined;
}) => (
  <CommandPrimitive.List
    ref={ref}
    className={cn("max-h-[300px] overflow-y-auto overflow-x-hidden", className)}
    {...props}
  />
);
CommandList.displayName = CommandPrimitive.List.displayName;

const CommandEmpty = ({
  ref,
  ...props
}: CommandEmptyProps & {
  ref?: React.Ref<React.ElementRef<typeof CommandPrimitive.Empty>> | undefined;
}) => <CommandPrimitive.Empty ref={ref} className="py-6 text-center text-sm" {...props} />;
CommandEmpty.displayName = CommandPrimitive.Empty.displayName;

const CommandGroup = ({
  className,
  ref,
  ...props
}: CommandGroupProps & {
  ref?: React.Ref<React.ElementRef<typeof CommandPrimitive.Group>> | undefined;
}) => (
  <CommandPrimitive.Group
    ref={ref}
    className={cn(
      "overflow-hidden p-1 text-foreground [&_[cmdk-group-heading]]:px-2 [&_[cmdk-group-heading]]:py-1.5 [&_[cmdk-group-heading]]:text-xs [&_[cmdk-group-heading]]:font-medium [&_[cmdk-group-heading]]:text-muted-foreground",
      className,
    )}
    {...props}
  />
);
CommandGroup.displayName = CommandPrimitive.Group.displayName;

const CommandSeparator = ({
  className,
  ref,
  ...props
}: CommandSeparatorProps & {
  ref?: React.Ref<React.ElementRef<typeof CommandPrimitive.Separator>> | undefined;
}) => (
  <CommandPrimitive.Separator
    ref={ref}
    className={cn("-mx-1 h-px bg-border", className)}
    {...props}
  />
);
CommandSeparator.displayName = CommandPrimitive.Separator.displayName;

const CommandItem = ({
  className,
  ref,
  ...props
}: CommandItemProps & {
  ref?: React.Ref<React.ElementRef<typeof CommandPrimitive.Item>> | undefined;
}) => (
  <CommandPrimitive.Item
    ref={ref}
    className={cn(overlayPrimitiveClassNames.commandItem, className)}
    {...props}
  />
);
CommandItem.displayName = CommandPrimitive.Item.displayName;

const defaultResultsLabel = (count: number | undefined, search: string) => {
  if (typeof count !== "number") return "Command results updated.";
  if (search.trim().length === 0) return `${count} command results available.`;
  return `${count} command results available for ${search}.`;
};

const CommandResults = ({
  className,
  count,
  search = "",
  label = defaultResultsLabel,
  children,
  ref,
  ...props
}: CommandResultsProps & { ref?: React.Ref<HTMLDivElement> | undefined }) => (
  <div
    ref={ref}
    aria-atomic="true"
    aria-live="polite"
    className={cn("sr-only", className)}
    {...props}
  >
    {children ?? label(count, search)}
  </div>
);
CommandResults.displayName = "CommandResults";

const shortcutKeyId = (key: React.ReactNode) => {
  if (typeof key === "string" || typeof key === "number") return String(key);
  if (React.isValidElement(key) && key.key != null) return String(key.key);
  return String(key);
};

const CommandShortcut = ({ className, keys, label, children, ...props }: CommandShortcutProps) => {
  const shortcutKeys = keys ?? (children != null ? [children] : []);

  return (
    <span
      className={cn("ml-auto flex shrink-0 items-center gap-1 text-muted-foreground", className)}
      {...props}
    >
      {label ? <span className="sr-only">{label}</span> : null}
      {shortcutKeys.map((key) => (
        <Kbd key={shortcutKeyId(key)} aria-hidden={label ? true : undefined} small>
          {key}
        </Kbd>
      ))}
    </span>
  );
};
CommandShortcut.displayName = "CommandShortcut";

export {
  Command,
  CommandDialog,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
  CommandResults,
  CommandSeparator,
  CommandShortcut,
};

"use client";

import { Dialog as BaseDialog } from "@base-ui/react/dialog";
import { Cross as X } from "@nebutra/icons";
import * as React from "react";
import { overlayClassNames, overlayZIndex } from "../tokens/components/overlay";
import { cn } from "../utils/cn";
import { overlayPrimitiveClassNames } from "./overlay";

// We keep these standard export names so the rest of the application using Nebutra UI doesn't break.
const Dialog = BaseDialog.Root;
const DialogPortal = BaseDialog.Portal;

const DialogTrigger = ({
  asChild,
  children,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<typeof BaseDialog.Trigger> & { asChild?: boolean } & {
  ref?: React.Ref<HTMLButtonElement> | undefined;
}) => {
  if (asChild && React.isValidElement(children)) {
    return (
      <BaseDialog.Trigger
        ref={ref}
        {...props}
        render={children as React.ReactElement<Record<string, unknown>>}
      />
    );
  }
  return (
    <BaseDialog.Trigger ref={ref} {...props}>
      {children}
    </BaseDialog.Trigger>
  );
};
DialogTrigger.displayName = "DialogTrigger";

const DialogClose = ({
  asChild,
  children,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<typeof BaseDialog.Close> & { asChild?: boolean } & {
  ref?: React.Ref<HTMLButtonElement> | undefined;
}) => {
  if (asChild && React.isValidElement(children)) {
    return (
      <BaseDialog.Close
        ref={ref}
        {...props}
        render={children as React.ReactElement<Record<string, unknown>>}
      />
    );
  }
  return (
    <BaseDialog.Close ref={ref} {...props}>
      {children}
    </BaseDialog.Close>
  );
};
DialogClose.displayName = "DialogClose";

const DialogOverlay = ({
  className,
  style,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<typeof BaseDialog.Backdrop> & {
  ref?: React.Ref<HTMLDivElement> | undefined;
}) => (
  <BaseDialog.Backdrop
    ref={ref}
    className={cn(overlayClassNames.backdrop, className)}
    style={{ zIndex: overlayZIndex.backdrop, ...style }}
    {...props}
  />
);
DialogOverlay.displayName = "DialogOverlay";

const DialogContent = ({
  className,
  children,
  style,
  ref,
  ...props
}: React.ComponentPropsWithoutRef<typeof BaseDialog.Popup> & {
  ref?: React.Ref<HTMLDivElement> | undefined;
}) => (
  <DialogPortal>
    <DialogOverlay />
    <BaseDialog.Popup
      ref={ref}
      className={cn(
        overlayClassNames.modalSurface,
        overlayPrimitiveClassNames.modalSurface,
        className,
      )}
      style={{ zIndex: overlayZIndex.modal, ...style }}
      {...props}
    >
      {children}
      <DialogClose className={overlayClassNames.closeButton}>
